function seasonProductCard(code){const existing={K:'Killawatt Freestyle Highlighter',D:'Diamond Bomb All-Over Diamond Veil',C:'Match Stix Contour Skinstick',R:'Cheeks Out Freestyle Cream Blush',V:'Fenty Icon Velvet Liquid Lipstick'};if(existing[code])return productCard(existing[code]);const p=SEASON_PRODUCT_CATALOG[code];if(!p)return '';return `<article class="product-card product-with-image"><figure class="product-figure"><a class="product-image-link" href="${p.url}" target="_blank" rel="noopener noreferrer"><img src="${p.image}" alt="${esc(p.name+' — '+p.shade)}" width="640" height="800" loading="lazy" decoding="async"></a><figcaption>${tr('图示色号','Shown shade')} · ${esc(p.shade)}</figcaption></figure><div class="product-copy"><a class="product-title" href="${p.url}" target="_blank" rel="noopener noreferrer">${esc(p.name)} <span>↗</span></a><div class="product-detail"><span>${tr('产品特点与用法','FORMULA & USE')}</span><p>${esc(tr(p.zh,p.en))}</p></div><small>${tr('图片与产品资料：Fenty 官网','Imagery & product details: Fenty official site')}</small></div></article>`}

// Shared rarity symbols connect the mystery legend and the revealed story seal.
function rarityIcon(rarity){const paths={common:'<path d="M20 8C12 0 4 10 12 18C4 26 14 34 20 26C28 34 36 24 28 18C36 10 26 0 20 8Z"/><circle cx="20" cy="18" r="4"/>',rare:'<path d="M9 8H31L37 17L20 34L3 17Z M3 17H37 M9 8L15 17L20 34L25 17L31 8 M15 17L20 8L25 17"/>',hidden:'<path d="M20 3L24 13L35 10L30 20L36 28L25 27L20 37L15 27L4 28L10 20L5 10L16 13Z"/><path d="M20 13L22 18L27 20L22 22L20 27L18 22L13 20L18 18Z"/>'};return `<svg class="rarity-icon" viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round" aria-hidden="true">${paths[rarity]}</svg>`;}
function seasonRarityLegend(){return `<div class="rarity-legend" aria-label="${tr('剧本款式分布','Story collection breakdown')}">${[['common',5],['rare',3],['hidden',1]].map(([rarity,count])=>`<span class="rarity-token rarity-${rarity}">${rarityIcon(rarity)}<span><strong>${count}</strong> ${tr(...rarityNames[rarity])}</span></span>`).join('')}</div>`;}
function seasonStoryBadge(season){return `<div class="season-story-badge rarity-${season.story.rarity}" data-event="${season.eventId}"><span class="badge-spark s1" aria-hidden="true">✦</span><span class="badge-spark s2" aria-hidden="true">✧</span><span class="badge-spark s3" aria-hidden="true">✦</span><span class="badge-spark s4" aria-hidden="true">✧</span>${rarityIcon(season.story.rarity)}<span class="badge-event">${tr(season.event.zh,season.event.en)}</span><strong>${tr(...rarityNames[season.story.rarity])}</strong></div>`;}
